    return evolution_checkpoint(_evolution(), AT3, AT3)


def _items():
    return [
        {"id": "beta", "proof": _proof_middle()},
        {"id": "alpha", "proof": _proof_head()},
        {"id": "伽马", "proof": _proof_single()},
    ]


def _member_digest(previous, item_id, proof):
    payload = {"id": item_id, "proof": proof}
    canonical = json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(
        previous.encode("ascii") + canonical.encode("utf-8")
    ).hexdigest()


